import type { TestTarget } from "./targets.ts";

export interface RenderOptions {
  /** Module name of the saved request, without extension. */
  name: string;
  /** Import specifier for the saved module, relative to the output file. */
  importPath: string;
}

/**
 * Every generated file starts with this marker; regeneration replaces only
 * files it can identify as its own, so hand-written tests are never clobbered.
 */
export const GENERATED_BY = "// Generated by postui gen";

/**
 * Render one self-contained test file for the target framework: raw
 * framework-native code (describe/test/expect, or node:test + assert) with
 * no postui import, no loader, and no intermediate assertion layer. The
 * emitted file imports the saved module like any other project file and
 * reads $ENV values from the environment at test time; while any referenced
 * variable is unset, the test skips.
 */
export function renderTest(target: TestTarget, opts: RenderOptions): string {
  switch (target) {
    case "vitest":
      return renderJestLike("vitest", opts);
    case "bun:test":
      return renderJestLike("bun:test", opts);
    case "node:test":
      return renderNodeTest(opts);
  }
}

// Shared helper block emitted into every generated file, keeping each file
// self-contained (String.raw preserves the regex backslashes verbatim).
const HELPERS = String.raw`
type FormEntry = { name: string; value?: string; file?: string };
interface SavedRequest {
  method: string;
  url: string;
  headers?: Record<string, string>;
  body?: null | string | FormEntry[];
}

const ENV_REF = /\$(?:\{([A-Za-z_][A-Za-z0-9_]*)\}|([A-Za-z_][A-Za-z0-9_]*))/g;

/** Every string value the request carries, for $ENV scanning. */
function valuesOf(request: SavedRequest): string[] {
  const values = [request.url];
  for (const value of Object.values(request.headers ?? {})) values.push(value);
  if (typeof request.body === "string") values.push(request.body);
  if (Array.isArray(request.body)) {
    for (const entry of request.body) {
      if (typeof entry.value === "string") values.push(entry.value);
      if (typeof entry.file === "string") values.push(entry.file);
    }
  }
  return values;
}

/** Names of environment variables the request references but that are unset. */
function missingEnvNames(request: SavedRequest): string[] {
  const missing = new Set<string>();
  for (const value of valuesOf(request)) {
    for (const match of value.matchAll(ENV_REF)) {
      const name = match[1] ?? match[2];
      if (name !== undefined && process.env[name] === undefined) missing.add(name);
    }
  }
  return [...missing];
}

/** Replace every $NAME (braced or bare) with its environment value. */
function resolveEnv(value: string): string {
  return value.replace(ENV_REF, (whole, braced, bare) => {
    const name = braced ?? bare;
    const resolved = name === undefined ? undefined : process.env[name];
    if (resolved === undefined) {
      throw new Error("environment variable " + name + " is not set (referenced as " + whole + ")");
    }
    return resolved;
  });
}

/** The saved request as a fetch call, with $ENV values resolved. */
async function toFetchInit(request: SavedRequest): Promise<{ url: string; init: RequestInit }> {
  const headers: Record<string, string> = {};
  for (const [name, value] of Object.entries(request.headers ?? {})) {
    headers[name] = resolveEnv(value);
  }
  let body: BodyInit | undefined;
  const raw = request.body;
  if (typeof raw === "string") {
    body = resolveEnv(raw);
  } else if (Array.isArray(raw)) {
    const form = new FormData();
    for (const entry of raw) {
      if (typeof entry.file === "string") {
        const { readFile } = await import("node:fs/promises");
        form.append(entry.name, new Blob([await readFile(resolveEnv(entry.file))]));
      } else if (typeof entry.value === "string") {
        form.append(entry.name, resolveEnv(entry.value));
      }
    }
    body = form;
    // fetch adds the multipart boundary itself; a saved content-type would corrupt it
    for (const name of Object.keys(headers)) {
      if (name.toLowerCase() === "content-type") delete headers[name];
    }
  }
  const method = request.method.toUpperCase();
  const init: RequestInit = { method, headers };
  if (body !== undefined && method !== "GET" && method !== "HEAD") init.body = body;
  return { url: resolveEnv(request.url), init };
}
`;

function header(target: TestTarget, opts: RenderOptions): string {
  return (
    `${GENERATED_BY} (${target}) from ${opts.importPath} — edit freely.\n` +
    `// Values like $NAME resolve from the environment when the test runs; while\n` +
    `// any referenced variable is unset, the test skips instead of failing.\n`
  );
}

/** vitest and bun:test share the jest-like API surface; the import differs. */
function renderJestLike(source: "vitest" | "bun:test", opts: RenderOptions): string {
  return (
    header(source, opts) +
    "\n" +
    `import { describe, expect, test } from "${source}";\n` +
    `import { request } from "${opts.importPath}";\n` +
    HELPERS +
    "\n" +
    `const missing = missingEnvNames(request);\n` +
    "\n" +
    `describe("${opts.name}", () => {\n` +
    `  test.skipIf(missing.length > 0)(request.method + " " + request.url, async () => {\n` +
    `    const { url, init } = await toFetchInit(request);\n` +
    `    const response = await fetch(url, init);\n` +
    `    // Default sanity assertion — edit to match what this endpoint promises.\n` +
    `    expect(response.status).toBeLessThan(500);\n` +
    `  });\n` +
    `});\n`
  );
}

function renderNodeTest(opts: RenderOptions): string {
  return (
    header("node:test", opts) +
    "\n" +
    `import { describe, test } from "node:test";\n` +
    `import assert from "node:assert/strict";\n` +
    `import { request } from "${opts.importPath}";\n` +
    HELPERS +
    "\n" +
    `const missing = missingEnvNames(request);\n` +
    `const skipReason = missing.length > 0\n` +
    `  ? "missing environment variables: " + missing.join(", ")\n` +
    `  : false;\n` +
    "\n" +
    `describe("${opts.name}", () => {\n` +
    `  test(request.method + " " + request.url, { skip: skipReason }, async () => {\n` +
    `    const { url, init } = await toFetchInit(request);\n` +
    `    const response = await fetch(url, init);\n` +
    `    // Default sanity assertion — edit to match what this endpoint promises.\n` +
    `    assert.ok(response.status < 500, "unexpected status: " + response.status);\n` +
    `  });\n` +
    `});\n`
  );
}
